def is_majority(arr, n, x):
    # Function to perform binary search for the first occurrence of x
    def binary_search(arr, low, high, x):
        if high >= low:
            mid = (low + high) // 2
            # If the element at mid is x and it's the first occurrence
            if (mid == 0 or x > arr[mid-1]) and arr[mid] == x:
                return mid
            # If x is greater, ignore left half
            elif x > arr[mid]:
                return binary_search(arr, (mid + 1), high, x)
            # If x is smaller, ignore right half
            else:
                return binary_search(arr, low, (mid - 1), x)
        # Element is not present
        return -1

    # Find the first occurrence of x
    first_occurrence = binary_search(arr, 0, n-1, x)

    # If the element is not present or its first occurrence is in the second half,
    # it cannot be the majority element
    if first_occurrence == -1 or (n - first_occurrence) < (n // 2 + 1):
        return False

    return True

