def get_total_number_of_sequences(m, n):
    def helper(current_length, upper_bound):
        if current_length == n:
            return 1
        total = 0
        for next_val in range(upper_bound, m // (2 ** (n - current_length)) + 1):
            total += helper(current_length + 1, next_val * 2)
        return total

    results = [helper(1, start) for start in range(1, m // (2 ** (n - 1)) + 1)]
    return sum(results)

